-- ── story 2-5a: attachments — the file-storage foundation ────────────────
-- Generated by drizzle-kit (the table and its seven indexes) and hand-amended
-- around the generated part: the fail-fast guard, every CHECK, RLS and the
-- post-migration probe (drizzle-kit is blind to all three; `bun run
-- db:generate` afterwards reports "No schema changes").
--
-- Additive: one new tenant-scoped table, empty at deploy. No data is
-- rewritten, no existing table is touched (no lock on a populated table), no
-- foreign keys (IMPLEMENTATION-GUIDE §3). Every index is `IF NOT EXISTS`
-- (guide §3, 6-2a A3) and sits outside any DO block.
--
-- The status machine (spec Design Notes, A2/A10/A13):
--   uploading ─device─► staged ─claim─► attached ─remove─► removed
--   uploading ─device, ref awaited|expired─► FILL that row → attached
--   claim, no ref row ─► awaited ─fill─► attached ; awaited ─remove─► removed (no object)
--   awaited ─age─► expired ─fill─► attached
--   uploading ─web─► attached (the owner is set at finalize)
--   uploading|staged ─age─► discarded ; removed|discarded ─delete─► purged_at
-- Every implication is its own NAMED CHECK, so each refused probe names its
-- arm; a nullable column always says `IS NULL OR …` / `IS NOT NULL AND …`
-- (guide §3).

-- ── 0. fail-fast ─────────────────────────────────────────────────────────
DO $$
BEGIN
	IF EXISTS (
		SELECT 1 FROM information_schema.tables
		 WHERE table_schema = 'public' AND table_name = 'attachments'
	) THEN
		RAISE EXCEPTION 'migration 0095: the attachments table already exists — this migration has already been applied.';
	END IF;
END $$;
--> statement-breakpoint
CREATE TABLE "attachments" (
	"id" uuid PRIMARY KEY NOT NULL,
	"tenant_id" uuid NOT NULL,
	"client_id" uuid,
	"warehouse_id" uuid,
	"purpose" text NOT NULL,
	"status" text NOT NULL,
	"source" text NOT NULL,
	"owner_type" text,
	"owner_id" uuid,
	"owner_parent_id" uuid,
	"client_ref" text,
	"upload_key" text,
	"upload_hash" text,
	"raw_sha256" text,
	"object_key" text,
	"content_type" text,
	"byte_size" integer,
	"sha256" text,
	"width" integer,
	"height" integer,
	"captured_at" timestamp with time zone,
	"uploaded_at" timestamp with time zone,
	"device_id" uuid,
	"created_by" uuid,
	"removed_by" uuid,
	"removed_at" timestamp with time zone,
	"removed_reason" text,
	"purged_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL
);
--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS "attachments_tenant_client_ref_unique" ON "attachments" USING btree ("tenant_id","client_ref") WHERE client_ref is not null and status <> 'discarded';--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS "attachments_tenant_upload_key_unique" ON "attachments" USING btree ("tenant_id","upload_key") WHERE status = 'uploading';--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS "attachments_tenant_object_key_unique" ON "attachments" USING btree ("tenant_id","object_key") WHERE object_key is not null and purged_at is null;--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "attachments_tenant_parent_idx" ON "attachments" USING btree ("tenant_id","owner_parent_id","owner_id") WHERE owner_parent_id is not null;--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "attachments_tenant_device_staged_idx" ON "attachments" USING btree ("tenant_id","device_id") WHERE status = 'staged';--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "attachments_tenant_sweep_idx" ON "attachments" USING btree ("tenant_id","status","created_at") WHERE status in ('uploading', 'staged', 'awaited') or (status in ('removed', 'discarded') and purged_at is null);--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "attachments_sweep_discovery_idx" ON "attachments" USING btree ("status","created_at");--> statement-breakpoint
