ALTER TABLE "attachments" ADD CONSTRAINT "attachments_purpose_check" CHECK ("purpose" IN ('receipt-damage'));--> statement-breakpoint
ALTER TABLE "attachments" ADD CONSTRAINT "attachments_status_check" CHECK ("status" IN ('uploading','staged','awaited','attached','removed','expired','discarded'));--> statement-breakpoint
ALTER TABLE "attachments" ADD CONSTRAINT "attachments_source_check" CHECK ("source" IN ('handheld','web'));--> statement-breakpoint
ALTER TABLE "attachments" ADD CONSTRAINT "attachments_owner_type_check" CHECK ("owner_type" IS NULL OR "owner_type" IN ('goods_receipt_line'));--> statement-breakpoint
ALTER TABLE "attachments" ADD CONSTRAINT "attachments_owner_together" CHECK (num_nulls("owner_type", "owner_id", "owner_parent_id") IN (0, 3));--> statement-breakpoint
ALTER TABLE "attachments" ADD CONSTRAINT "attachments_owned_statuses" CHECK ("status" NOT IN ('awaited','attached','removed','expired') OR "owner_id" IS NOT NULL);--> statement-breakpoint
ALTER TABLE "attachments" ADD CONSTRAINT "attachments_unowned_statuses" CHECK ("status" NOT IN ('uploading','staged') OR "owner_id" IS NULL);--> statement-breakpoint
ALTER TABLE "attachments" ADD CONSTRAINT "attachments_object_together" CHECK (num_nulls("object_key", "content_type", "byte_size", "sha256", "width", "height") IN (0, 6));--> statement-breakpoint
ALTER TABLE "attachments" ADD CONSTRAINT "attachments_object_required" CHECK ("status" NOT IN ('uploading','staged','attached','discarded') OR "object_key" IS NOT NULL);--> statement-breakpoint
ALTER TABLE "attachments" ADD CONSTRAINT "attachments_object_absent" CHECK ("status" NOT IN ('awaited','expired') OR "object_key" IS NULL);--> statement-breakpoint
ALTER TABLE "attachments" ADD CONSTRAINT "attachments_purged_status" CHECK ("purged_at" IS NULL OR ("status" IN ('removed','discarded') AND "object_key" IS NOT NULL));--> statement-breakpoint
ALTER TABLE "attachments" ADD CONSTRAINT "attachments_content_type_check" CHECK ("content_type" IS NULL OR "content_type" IN ('image/jpeg','image/png','image/webp'));--> statement-breakpoint
ALTER TABLE "attachments" ADD CONSTRAINT "attachments_size_check" CHECK ("byte_size" IS NULL OR "byte_size" BETWEEN 1 AND 10485760);--> statement-breakpoint
ALTER TABLE "attachments" ADD CONSTRAINT "attachments_dims_check" CHECK (("width" IS NULL OR "width" BETWEEN 1 AND 8000) AND ("height" IS NULL OR "height" BETWEEN 1 AND 8000));--> statement-breakpoint
ALTER TABLE "attachments" ADD CONSTRAINT "attachments_sha_check" CHECK (("sha256" IS NULL OR "sha256" ~ '^[0-9a-f]{64}$') AND ("raw_sha256" IS NULL OR "raw_sha256" ~ '^[0-9a-f]{64}$') AND ("upload_hash" IS NULL OR "upload_hash" ~ '^[0-9a-f]{64}$'));--> statement-breakpoint
ALTER TABLE "attachments" ADD CONSTRAINT "attachments_client_ref_check" CHECK ("client_ref" IS NULL OR "client_ref" ~ '^[0-9A-HJKMNP-TV-Z]{26}$');--> statement-breakpoint
ALTER TABLE "attachments" ADD CONSTRAINT "attachments_ref_statuses" CHECK ("status" NOT IN ('staged','awaited') OR "client_ref" IS NOT NULL);--> statement-breakpoint
ALTER TABLE "attachments" ADD CONSTRAINT "attachments_uploading_no_ref" CHECK ("status" <> 'uploading' OR "client_ref" IS NULL);--> statement-breakpoint
ALTER TABLE "attachments" ADD CONSTRAINT "attachments_handheld_device" CHECK ("source" <> 'handheld' OR "device_id" IS NOT NULL);--> statement-breakpoint
ALTER TABLE "attachments" ADD CONSTRAINT "attachments_upload_pairing" CHECK ("status" <> 'uploading' OR ("upload_key" IS NOT NULL AND "upload_hash" IS NOT NULL AND "raw_sha256" IS NOT NULL));--> statement-breakpoint
ALTER TABLE "attachments" ADD CONSTRAINT "attachments_removed_pairing" CHECK (("status" = 'removed' AND "removed_by" IS NOT NULL AND "removed_at" IS NOT NULL AND "removed_reason" IS NOT NULL AND char_length("removed_reason") BETWEEN 1 AND 200) OR ("status" <> 'removed' AND "removed_by" IS NULL AND "removed_at" IS NULL AND "removed_reason" IS NULL));--> statement-breakpoint
-- ── hand-amended: RLS — the tenant arm plus the 0041 client clause (0084) ──
-- A portal-stamped transaction (`app.client_id` set) sees only its own
-- client's attachments — never an unattributed one (a null `client_id` never
-- equals a stamp: a device upload's `uploading`/`staged` row has none) — and
-- cannot write one; an operator one (unset) sees the tenant's.
ALTER TABLE "attachments" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE POLICY "attachments_tenant_isolation" ON "attachments"
	USING (
		"tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid
		AND (
			NULLIF(current_setting('app.client_id', true), '') IS NULL
			OR "client_id" = NULLIF(current_setting('app.client_id', true), '')::uuid
		)
	)
	WITH CHECK (
		"tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid
		AND (
			NULLIF(current_setting('app.client_id', true), '') IS NULL
			OR "client_id" = NULLIF(current_setting('app.client_id', true), '')::uuid
		)
	);--> statement-breakpoint
-- ── the post-migration assertion (the 0086 model) ─────────────────────────
-- Made-up uuids. Every shape is built from one valid `attached` web row
-- (`base`) with a per-probe override merged over it (`jsonb_populate_record`),
-- each with a fresh id and object key. The accepted shapes are inserted first
-- and rolled back by a sentinel exception, so a CHECK that refused everything
-- fails the migration; each refused shape runs in its own subtransaction and
-- must be refused BY ITS NAMED CONSTRAINT (guide §3). A `DUP:` probe inserts
-- the same override twice (a partial unique key).
DO $$
DECLARE
	t uuid := gen_random_uuid();
	u uuid := gen_random_uuid();
	base jsonb;
	rec jsonb;
	refused_by text;
	probe record;
	shape record;
BEGIN
	base := jsonb_build_object(
		'tenant_id', t, 'client_id', gen_random_uuid(), 'warehouse_id', gen_random_uuid(),
		'purpose', 'receipt-damage', 'status', 'attached', 'source', 'web',
		'owner_type', 'goods_receipt_line', 'owner_id', gen_random_uuid(), 'owner_parent_id', gen_random_uuid(),
		'client_ref', NULL, 'upload_key', NULL, 'upload_hash', repeat('b', 64), 'raw_sha256', repeat('c', 64),
		'content_type', 'image/jpeg', 'byte_size', 1000, 'sha256', repeat('a', 64), 'width', 1600, 'height', 1200,
		'captured_at', now(), 'uploaded_at', now(), 'device_id', gen_random_uuid(), 'created_by', u,
		'removed_by', NULL, 'removed_at', NULL, 'removed_reason', NULL, 'purged_at', NULL,
		'created_at', now(), 'updated_at', now());
	-- (1) accepted shapes, every status with what it needs.
	BEGIN
		FOR shape IN SELECT * FROM (VALUES
			('uploading device', '{"status":"uploading","source":"handheld","client_id":null,"warehouse_id":null,"owner_type":null,"owner_id":null,"owner_parent_id":null,"client_ref":null,"upload_key":"PROBE-K1","created_by":null}'),
			('uploading web', '{"status":"uploading","source":"web","device_id":null,"client_id":null,"owner_type":null,"owner_id":null,"owner_parent_id":null,"client_ref":null,"upload_key":"PROBE-K2"}'),
			('staged', '{"status":"staged","source":"handheld","client_id":null,"warehouse_id":null,"owner_type":null,"owner_id":null,"owner_parent_id":null,"client_ref":"01JZ0000000000000000000001"}'),
			('awaited', '{"status":"awaited","source":"handheld","client_ref":"01JZ0000000000000000000002","object_key":null,"content_type":null,"byte_size":null,"sha256":null,"width":null,"height":null,"raw_sha256":null,"upload_key":null,"upload_hash":null,"uploaded_at":null,"captured_at":null}'),
			('expired', '{"status":"expired","source":"handheld","client_ref":"01JZ0000000000000000000003","object_key":null,"content_type":null,"byte_size":null,"sha256":null,"width":null,"height":null,"raw_sha256":null,"upload_key":null,"upload_hash":null,"uploaded_at":null}'),
			('attached handheld (an expired row filled)', '{"status":"attached","source":"handheld","client_ref":"01JZ0000000000000000000004"}'),
			('attached web', '{"status":"attached","source":"web","device_id":null,"client_id":null}'),
			('removed with an object', '{"status":"removed","removed_by":"%U%","removed_at":"2026-10-23T00:00:00Z","removed_reason":"Wrong line"}'),
			('removed without an object (a cancelled awaited)', '{"status":"removed","source":"handheld","client_ref":"01JZ0000000000000000000005","object_key":null,"content_type":null,"byte_size":null,"sha256":null,"width":null,"height":null,"raw_sha256":null,"upload_hash":null,"upload_key":null,"removed_by":"%U%","removed_at":"2026-10-23T00:00:00Z","removed_reason":"Never taken"}'),
			('removed and purged', '{"status":"removed","removed_by":"%U%","removed_at":"2026-10-23T00:00:00Z","removed_reason":"x","purged_at":"2026-11-23T00:00:00Z"}'),
			('discarded and purged', '{"status":"discarded","source":"handheld","owner_type":null,"owner_id":null,"owner_parent_id":null,"client_id":null,"purged_at":"2026-11-23T00:00:00Z"}')
		) AS s(name, override) LOOP
			rec := base || jsonb_build_object('id', gen_random_uuid(), 'object_key', 'tenants/probe/attachments/' || gen_random_uuid())
				|| replace(shape.override, '%U%', u::text)::jsonb;
			INSERT INTO "attachments" SELECT (jsonb_populate_record(NULL::"attachments", rec)).*;
		END LOOP;
		RAISE EXCEPTION USING ERRCODE = 'P0095', MESSAGE = 'rollback the accepted probes';
	EXCEPTION
		WHEN check_violation OR unique_violation OR not_null_violation THEN
			RAISE EXCEPTION 'migration 0095: an accepted shape (%) was refused (%).', shape.name, SQLERRM;
		WHEN SQLSTATE 'P0095' THEN
			NULL;
	END;
	-- (2) refused shapes, each by its named constraint.
	FOR probe IN SELECT * FROM (VALUES
		('purpose unknown', 'attachments_purpose_check', '{"purpose":"sds"}'),
		('status unknown', 'attachments_status_check', '{"status":"pending"}'),
		('source unknown', 'attachments_source_check', '{"source":"portal"}'),
		('owner type unknown', 'attachments_owner_type_check', '{"owner_type":"goods_receipt"}'),
		('owner partial', 'attachments_owner_together', '{"status":"uploading","upload_key":"PROBE-K9","owner_id":null,"owner_parent_id":null}'),
		('attached unowned', 'attachments_owned_statuses', '{"owner_type":null,"owner_id":null,"owner_parent_id":null}'),
		('staged owned', 'attachments_unowned_statuses', '{"status":"staged","source":"handheld","client_ref":"01JZ0000000000000000000011"}'),
		('object partial', 'attachments_object_together', '{"width":null}'),
		('attached without object', 'attachments_object_required', '{"object_key":null,"content_type":null,"byte_size":null,"sha256":null,"width":null,"height":null}'),
		('awaited with object', 'attachments_object_absent', '{"status":"awaited","source":"handheld","client_ref":"01JZ0000000000000000000012"}'),
		('attached purged', 'attachments_purged_status', '{"purged_at":"2026-11-23T00:00:00Z"}'),
		('content type gif', 'attachments_content_type_check', '{"content_type":"image/gif"}'),
		('size zero', 'attachments_size_check', '{"byte_size":0}'),
		('size over', 'attachments_size_check', '{"byte_size":10485761}'),
		('width 8001', 'attachments_dims_check', '{"width":8001}'),
		('height zero', 'attachments_dims_check', '{"height":0}'),
		('sha upper-case', 'attachments_sha_check', '{"sha256":"%SHAU%"}'),
		('raw sha short', 'attachments_sha_check', '{"raw_sha256":"abc"}'),
		('client ref lower-case', 'attachments_client_ref_check', '{"client_ref":"01jz0000000000000000000013"}'),
		('client ref with I', 'attachments_client_ref_check', '{"client_ref":"01JZI000000000000000000013"}'),
		('staged without ref', 'attachments_ref_statuses', '{"status":"staged","source":"handheld","owner_type":null,"owner_id":null,"owner_parent_id":null}'),
		('uploading with ref', 'attachments_uploading_no_ref', '{"status":"uploading","upload_key":"PROBE-K8","client_ref":"01JZ0000000000000000000014","owner_type":null,"owner_id":null,"owner_parent_id":null}'),
		('handheld without device', 'attachments_handheld_device', '{"source":"handheld","device_id":null}'),
		('uploading without hash', 'attachments_upload_pairing', '{"status":"uploading","upload_key":"PROBE-K7","upload_hash":null,"owner_type":null,"owner_id":null,"owner_parent_id":null}'),
		('removed without reason', 'attachments_removed_pairing', '{"status":"removed","removed_by":"%U%","removed_at":"2026-10-23T00:00:00Z"}'),
		('removed reason 201', 'attachments_removed_pairing', '{"status":"removed","removed_by":"%U%","removed_at":"2026-10-23T00:00:00Z","removed_reason":"%R201%"}'),
		('attached with removed_at', 'attachments_removed_pairing', '{"removed_at":"2026-10-23T00:00:00Z"}'),
		('duplicate client ref', 'attachments_tenant_client_ref_unique', 'DUP:{"client_ref":"01JZ0000000000000000000020"}'),
		('duplicate uploading key', 'attachments_tenant_upload_key_unique', 'DUP:{"status":"uploading","upload_key":"PROBE-DUP","owner_type":null,"owner_id":null,"owner_parent_id":null}'),
		('duplicate live object key', 'attachments_tenant_object_key_unique', 'DUP:{"object_key":"tenants/probe/attachments/dup"}')
	) AS p(name, expected, override) LOOP
		refused_by := NULL;
		BEGIN
			rec := base || jsonb_build_object('id', gen_random_uuid(), 'object_key', 'tenants/probe/attachments/' || gen_random_uuid())
				|| replace(replace(replace(regexp_replace(probe.override, '^DUP:', ''), '%U%', u::text), '%SHAU%', repeat('A', 64)), '%R201%', repeat('r', 201))::jsonb;
			INSERT INTO "attachments" SELECT (jsonb_populate_record(NULL::"attachments", rec)).*;
			IF probe.override LIKE 'DUP:%' THEN
				rec := rec || jsonb_build_object('id', gen_random_uuid());
				IF NOT (probe.override LIKE '%object_key%') THEN
					rec := rec || jsonb_build_object('object_key', 'tenants/probe/attachments/' || gen_random_uuid());
				END IF;
				INSERT INTO "attachments" SELECT (jsonb_populate_record(NULL::"attachments", rec)).*;
			END IF;
			RAISE EXCEPTION USING ERRCODE = 'P0095', MESSAGE = 'a refused probe was accepted';
		EXCEPTION
			WHEN check_violation OR unique_violation THEN
				GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
			WHEN SQLSTATE 'P0095' THEN
				refused_by := NULL;
		END;
		IF refused_by IS DISTINCT FROM probe.expected THEN
			RAISE EXCEPTION 'migration 0095: probe "%" was refused by % (expected %).', probe.name, coalesce(refused_by, 'nothing'), probe.expected;
		END IF;
	END LOOP;
	IF EXISTS (SELECT 1 FROM "attachments" WHERE "tenant_id" = t) THEN
		RAISE EXCEPTION 'migration 0095: a probe row survived.';
	END IF;
END $$;
